mapper.select:
SELECT a.id, u.name AS applicant_name, u.job_no, u.company, u.user_type, u.region, u.phone,
       a.audit_status, a.reject_reason, a.apply_time, a.audit_time
FROM sys_account_audit a
JOIN sys_user u ON u.id = a.user_id AND u.is_deleted = 0
WHERE 1 = 1
AND a.audit_status = #{status}
AND u.name LIKE CONCAT('%', #{name}, '%')
AND u.job_no = #{jobNo}
ORDER BY a.apply_time DESC, a.id DESC
LIMIT #{offset}, #{size}

SELECT id, user_id, audit_status, audit_user_id, audit_time, reject_reason, apply_time, create_time
FROM sys_account_audit
WHERE id = #{id}

mapper.update:
UPDATE sys_account_audit
SET audit_status = #{auditStatus},
    audit_user_id = #{auditUserId},
    audit_time = #{auditTime},
    reject_reason = #{rejectReason}
WHERE id = #{id}
